export class Vec4ArrayLike {
    static Create(x = 0, y = 0, z = 0, w = 0) {
        return [x, y, z, w];
    }
    static ApplyMatrix(matrix, vec) {
        return [
            matrix[0] * vec[0] +
                matrix[1] * vec[1] +
                matrix[2] * vec[2] +
                matrix[3] * vec[3],
            matrix[4] * vec[0] +
                matrix[5] * vec[1] +
                matrix[6] * vec[2] +
                matrix[7] * vec[3],
            matrix[8] * vec[0] +
                matrix[9] * vec[1] +
                matrix[10] * vec[2] +
                matrix[11] * vec[3],
            matrix[12] * vec[0] +
                matrix[13] * vec[1] +
                matrix[14] * vec[2] +
                matrix[15] * vec[3],
        ];
    }
    static RotateAroundPivot(matrix, vec, pivot) {
        const translatedVec = [
            vec[0] - pivot[0],
            vec[1] - pivot[1],
            vec[2] - pivot[2],
            vec[3] - pivot[3],
        ];
        const rotatedVec = Vec4ArrayLike.ApplyMatrix(matrix, translatedVec);
        return [
            rotatedVec[0] + pivot[0],
            rotatedVec[1] + pivot[1],
            rotatedVec[2] + pivot[2],
            rotatedVec[3] + pivot[3],
        ];
    }
    static Add(v1, v2) {
        return this.AddToRef(v1, v2, Vec4ArrayLike.Create());
    }
    static AddInPlace(v1, v2) {
        return this.AddToRef(v1, v2, v1);
    }
    static AddToRef(v1, v2, ref) {
        const [x1, y1, z1, w1] = v1;
        const [x2, y2, z2, w2] = v2;
        ref[0] = x1 + x2;
        ref[1] = y1 + y2;
        ref[2] = z1 + z2;
        ref[3] = w1 + w2;
        return ref;
    }
    static AddScalar(v, scalar) {
        return this.AddScalarToRef(v, scalar, Vec4ArrayLike.Create());
    }
    static AddScalarInPlace(v, scalar) {
        return this.AddScalarToRef(v, scalar, v);
    }
    static AddScalarToRef(v, scalar, ref) {
        const [x, y, z, w] = v;
        ref[0] = x + scalar;
        ref[1] = y + scalar;
        ref[2] = z + scalar;
        ref[3] = w + scalar;
        return ref;
    }
    static Subtract(v1, v2) {
        return this.SubtractToRef(v1, v2, Vec4ArrayLike.Create());
    }
    static SubtractInPlace(v1, v2) {
        return this.SubtractToRef(v1, v2, v1);
    }
    static SubtractToRef(v1, v2, ref) {
        const [x1, y1, z1, w1] = v1;
        const [x2, y2, z2, w2] = v2;
        ref[0] = x1 - x2;
        ref[1] = y1 - y2;
        ref[2] = z1 - z2;
        ref[3] = w1 - w2;
        return ref;
    }
    static SubtractScalar(v, scalar) {
        return this.SubtractScalarToRef(v, scalar, Vec4ArrayLike.Create());
    }
    static SubtractScalarInPlace(v, scalar) {
        return this.SubtractScalarToRef(v, scalar, v);
    }
    static SubtractScalarToRef(v, scalar, ref) {
        const [x, y, z, w] = v;
        ref[0] = x - scalar;
        ref[1] = y - scalar;
        ref[2] = z - scalar;
        ref[3] = w - scalar;
        return ref;
    }
    static Multiply(v1, v2) {
        return this.MultiplyToRef(v1, v2, Vec4ArrayLike.Create());
    }
    static MultiplyInPlace(v1, v2) {
        return this.MultiplyToRef(v1, v2, v1);
    }
    static MultiplyToRef(v1, v2, ref) {
        const [x1, y1, z1, w1] = v1;
        const [x2, y2, z2, w2] = v2;
        ref[0] = x1 * x2;
        ref[1] = y1 * y2;
        ref[2] = z1 * z2;
        ref[3] = w1 * w2;
        return ref;
    }
    static MultiplyScalar(v, scalar) {
        return this.MultiplyScalarToRef(v, scalar, Vec4ArrayLike.Create());
    }
    static MultiplyScalarInPlace(v, scalar) {
        return this.MultiplyScalarToRef(v, scalar, v);
    }
    static MultiplyScalarToRef(v, scalar, ref) {
        const [x, y, z, w] = v;
        ref[0] = x * scalar;
        ref[1] = y * scalar;
        ref[2] = z * scalar;
        ref[3] = w * scalar;
        return ref;
    }
    static Divide(v1, v2) {
        return this.DivideToRef(v1, v2, Vec4ArrayLike.Create());
    }
    static DivideInPlace(v1, v2) {
        return this.DivideToRef(v1, v2, v1);
    }
    static DivideToRef(v1, v2, ref) {
        const [x1, y1, z1, w1] = v1;
        const [x2, y2, z2, w2] = v2;
        ref[0] = x1 / x2;
        ref[1] = y1 / y2;
        ref[2] = z1 / z2;
        ref[3] = w1 / w2;
        return ref;
    }
    static DivideScalar(v, scalar) {
        return this.DivideScalarToRef(v, scalar, Vec4ArrayLike.Create());
    }
    static DivideScalarInPlace(v, scalar) {
        return this.DivideScalarToRef(v, scalar, v);
    }
    static DivideScalarToRef(v, scalar, ref) {
        const [x, y, z, w] = v;
        ref[0] = x / scalar;
        ref[1] = y / scalar;
        ref[2] = z / scalar;
        ref[3] = w / scalar;
        return ref;
    }
    static Normalize(v) {
        return this.NormalizeToRef(v, Vec4ArrayLike.Create());
    }
    static NormalizeInPlace(v) {
        return this.NormalizeToRef(v, v);
    }
    static NormalizeToRef(v, ref) {
        const len = Vec4ArrayLike.Length(v);
        const [x, y, z, w] = v;
        if (len === 0) {
            ref[0] = 0;
            ref[1] = 0;
            ref[2] = 0;
            ref[3] = 0;
        }
        else {
            ref[0] = x / len;
            ref[1] = y / len;
            ref[2] = z / len;
            ref[3] = w / len;
        }
        return ref;
    }
    static Lerp(v1, v2, t) {
        return this.LerpToRef(v1, v2, t, Vec4ArrayLike.Create());
    }
    static LerpToRef(v1, v2, t, ref) {
        const [x1, y1, z1, w1] = v1;
        const [x2, y2, z2, w2] = v2;
        ref[0] = x1 + t * (x2 - x1);
        ref[1] = y1 + t * (y2 - y1);
        ref[2] = z1 + t * (z2 - z1);
        ref[3] = w1 + t * (w2 - w1);
        return ref;
    }
    static Negate(v) {
        return this.NegateToRef(v, Vec4ArrayLike.Create());
    }
    static NegateInPlace(v) {
        return this.NegateToRef(v, v);
    }
    static NegateToRef(v, ref) {
        const [x, y, z, w] = v;
        ref[0] = -x;
        ref[1] = -y;
        ref[2] = -z;
        ref[3] = -w;
        return ref;
    }
    static Dot(v1, v2) {
        return v1[0] * v2[0] + v1[1] * v2[1] + v1[2] * v2[2] + v1[3] * v2[3];
    }
    static Length(v) {
        return Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2] + v[3] * v[3]);
    }
    static Distance(v1, v2) {
        return Vec4ArrayLike.Length(Vec4ArrayLike.Subtract(v1, v2));
    }
    static Equals(v1, v2) {
        return (v1[0] === v2[0] && v1[1] === v2[1] && v1[2] === v2[2] && v1[3] === v2[3]);
    }
    static Clone(v) {
        return [v[0], v[1], v[2], v[3]];
    }
    static Copy(target, source) {
        target[0] = source[0];
        target[1] = source[1];
        target[2] = source[2];
        return target;
    }
}
